// Function to setup navigation after PHP variables are loaded
function setupHadithNavigation() {
    const prevBtn = document.getElementById('prevSuraBtn');
    const nextBtn = document.getElementById('nextSuraBtn');

    if (!prevBtn || !nextBtn) return;

    // Get current collection and book from URL parameters
    const urlParams = new URLSearchParams(window.location.search);
    let currentCollection = parseInt(urlParams.get('collection')) || 1;
    let currentBook = parseInt(urlParams.get('book')) || 1;

    console.log('Navigation setup - Current book:', currentBook, 'Total books:', window.totalBookCount);

    // Previous button - decrease book by 1
    prevBtn.addEventListener('click', function() {
        if (currentBook > 1) {
            const newBook = currentBook - 1;
            const newUrl = `hadith.php?collection=${currentCollection}&book=${newBook}`;
            window.location.href = newUrl;
        }
    });

    // Next button - increase book by 1
    nextBtn.addEventListener('click', function() {
        const newBook = currentBook + 1;
        const newUrl = `hadith.php?collection=${currentCollection}&book=${newBook}`;
        window.location.href = newUrl;
    });

    // Disable previous button logic
    if (currentBook <= 1) {
        prevBtn.disabled = true;
        prevBtn.style.opacity = '0.5';
        prevBtn.style.cursor = 'not-allowed';
        console.log('Previous button disabled - at first book');
    } else {
        prevBtn.disabled = false;
        prevBtn.style.opacity = '1';
        prevBtn.style.cursor = 'pointer';
        console.log('Previous button enabled - not at first book');
    }

    // Disable next button if we're at the last book
    if (window.totalBookCount && currentBook >= window.totalBookCount) {
        nextBtn.disabled = true;
        nextBtn.style.opacity = '0.5';
        nextBtn.style.cursor = 'not-allowed';
        console.log('Next button disabled - at last book');
    } else {
        nextBtn.disabled = false;
        nextBtn.style.opacity = '1';
        nextBtn.style.cursor = 'pointer';
        console.log('Next button enabled - not at last book');
    }
}

// Try to setup navigation when DOM is ready
document.addEventListener('DOMContentLoaded', function() {
    // Wait a bit for PHP variables to be set, then setup navigation
    setTimeout(setupHadithNavigation, 100);
});

// Also try to setup navigation when window variables are available
if (typeof window.totalBookCount !== 'undefined') {
    setupHadithNavigation();
