                // Fetch narrator names
                fetch('get_narrators.php?ids=' + encodeURIComponent(narratorIds))
                    .then(response => response.json())
                    .then(data => {
                        const modalBody = document.getElementById('narratorsModalBody');
                        if (data.success && data.narrators.length > 0) {
                            // Get current URL parameters for referrer
                            const urlParams = new URLSearchParams(window.location.search);
                            const collection = urlParams.get('collection') || '';
                            const book = urlParams.get('book') || '';
                            const refUrl = 'hadith.php?collection=' + collection + '&book=' + book;

                            let html = '<div class="list-group">';
                            data.narrators.forEach(narrator => {
                                html += '<a href="scholars.php?id=' + narrator.id + '&ref=' + encodeURIComponent(refUrl) + '" class="list-group-item list-group-item-action">';
                                html += '<div class="d-flex w-100 justify-content-between align-items-center">';
