document.addEventListener('DOMContentLoaded', function() {
    // Handle Quran/Tafsir search form
    const searchForm = document.getElementById('searchForm');
    if (searchForm) {
        searchForm.addEventListener('submit', function(e) {
        e.preventDefault();
